83	function toSerializableProviderRef(provider: unknown): unknown {
84	  if (isApiProvider(provider)) {
85	    return sanitizeProvider(provider);
86	  }
87	  if (Array.isArray(provider)) {
88	    return provider.map(toSerializableProviderRef);
89	  }
90	  return provider;
91	}
92	
93	function isRecord(value: unknown): value is Record<string, unknown> {
94	  return Boolean(value && typeof value === 'object' && !Array.isArray(value));
95	}
96	
97	function withSerializableProvider<T extends Record<string, unknown>>(record: T): T {
98	  if (!isApiProvider(record.provider)) {
99	    return record;
100	  }
101	  return {
102	    ...record,
103	    provider: sanitizeProvider(record.provider),
104	  };
105	}
106	
107	/**
108	 * Function-valued transforms are first-class at runtime but are silently dropped
109	 * by `JSON.stringify`. Persisted eval configs (drizzle-stored) must never retain
110	 * a function reference, so replace every `transform`-like field with a
111	 * `[inline function]: name` marker. Non-function values pass through unchanged.
112	 *
113	 * `droppedRef.value` is flipped to `true` the first time a function is replaced
114	 * so the caller can emit a single warning instead of logging per field.
115	 */
116	function replaceFunctionTransforms<T extends Record<string, unknown>>(
117	  record: T,
118	  droppedRef: { value: boolean },
119	): T {
120	  let result: T | undefined;
121	  for (const key of TRANSFORM_KEYS) {
122	    const value = record[key];
123	    if (!isTransformFunction(value)) {
124	      continue;
125	    }
126	    if (!result) {
127	      result = { ...record };
128	    }
129	    (result as Record<string, unknown>)[key] = value.name
130	      ? `${INLINE_FUNCTION_LABEL}: ${value.name}`
131	      : INLINE_FUNCTION_LABEL;
132	    droppedRef.value = true;
133	  }
134	  return result ?? record;
135	}
136	
137	function toSerializableAssertion(assertion: unknown, droppedRef: { value: boolean }): unknown {
138	  if (!isRecord(assertion)) {
139	    return assertion;
140	  }
141	
142	  let sanitizedAssertion = withSerializableProvider(assertion);
143	  sanitizedAssertion = replaceFunctionTransforms(sanitizedAssertion, droppedRef);
144	
145	  if (Array.isArray(assertion.assert)) {
146	    sanitizedAssertion = {
147	      ...sanitizedAssertion,
148	      assert: assertion.assert.map((a) => toSerializableAssertion(a, droppedRef)),
149	    };
150	  }
151	
152	  return sanitizedAssertion;
153	}
154	
155	function toSerializableTestCase(test: unknown, droppedRef: { value: boolean }): unknown {
156	  if (!isRecord(test)) {
157	    return test;
158	  }
159	
160	  let sanitizedTest = withSerializableProvider(test);
161	
162	  if (isRecord(test.options)) {
163	    let options = withSerializableProvider(test.options);
164	    options = replaceFunctionTransforms(options, droppedRef);
165	    if (options !== test.options) {
166	      sanitizedTest = {
167	        ...sanitizedTest,
168	        options,
169	      };
170	    }
171	  }
172	
173	  if (Array.isArray(test.assert)) {
174	    sanitizedTest = {
175	      ...sanitizedTest,
176	      assert: test.assert.map((a) => toSerializableAssertion(a, droppedRef)),
177	    };
178	  }
179	
180	  return sanitizedTest;
181	}
